const PORTAL = '247728856';
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773', WON: '4456833775', LOST: '4456833776' };
const CHANNEL = { HOT: 'C0CB16L6UD6', LEADS: 'C0CAAG03B1A' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso ?? '');
  return new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
};
const hhmm = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
};

// One active Calendly booking → which HubSpot contact and deal it belongs to.
// The lead id from the booking (utm_content) only counts if that deal is linked to
// the contact with the booking's email: anyone could type a lead id into a URL.
const b = $('From poller').first().json;
const contactId = String($('Upsert contact').first().json.results[0].id);
const read = $('Read deals').first().json;
const deals = (read.statusCode === 200 || read.statusCode === 207) ? (read.body?.results ?? []) : [];

const open = deals.filter((d) => d.properties?.pipeline === PIPELINE && ![STAGE.WON, STAGE.LOST].includes(d.properties?.dealstage));
let deal = b.leadId ? open.find((d) => d.properties?.tca_lead_id === b.leadId) : null;
let matchedBy = deal ? 'lead id' : '';
if (!deal && open.length) {
  deal = [...open].sort((x, y) => Date.parse(y.properties.createdate) - Date.parse(x.properties.createdate))[0];
  matchedBy = 'newest open deal';
}

// HubSpot's 2026-09 API requires an owner on a new meeting: the deal's owner, else the account owner (Neil).
const DEFAULT_OWNER = '101409351';
const props = {
  hubspot_owner_id: String(deal?.properties?.hubspot_owner_id || DEFAULT_OWNER),
  hs_timestamp: b.start,
  hs_meeting_title: (b.eventName || 'Call') + ' with ' + (b.name || b.email),
  hs_meeting_body: 'Booked through Calendly from the website. Matched to the deal by ' + (matchedBy || 'nothing: no open TCA deal, logged on the contact') + '.',
  hs_meeting_start_time: b.start,
  hs_meeting_end_time: b.end,
  hs_meeting_outcome: 'SCHEDULED',
  tca_calendly_invitee: b.inviteeUri,
};
if (b.joinUrl) { props.hs_meeting_location = b.joinUrl; props.hs_meeting_external_url = b.joinUrl; }

return [{ json: {
  contactId,
  dealId: deal ? String(deal.id) : null,
  dealName: deal?.properties?.dealname ?? null,
  dealStage: deal?.properties?.dealstage ?? null,
  bucket: deal?.properties?.tca_lead_bucket ?? null,
  matchedBy: matchedBy || 'no open deal',
  moveToCallBooked: Boolean(deal) && [STAGE.NEW, STAGE.CONTACTED].includes(deal.properties.dealstage),
  meetingBody: {
    properties: props,
    associations: [{ to: { id: contactId }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 200 }] }],
  },
} }];

const PORTAL = '247728856';
const PIPELINE = '2630364862';
const STAGE = { NEW: '4456833770', CONTACTED: '4456833771', CALL: '4456833772', PROPOSAL: '4456833773', WON: '4456833775', LOST: '4456833776' };
const CHANNEL = { HOT: 'C0CB16L6UD6', LEADS: 'C0CAAG03B1A' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const when = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return String(iso ?? '');
  return new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', weekday: 'short', day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
};
const hhmm = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Manila', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
};

// "Call booked" card: one message from here instead of build 2's stage alert.
const b = $('From poller').first().json;
const p = $('Pick deal').first().json;
const url = p.dealId
  ? 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-3/' + p.dealId
  : 'https://app-na2.hubspot.com/contacts/' + PORTAL + '/record/0-1/' + p.contactId;
const lines = [
  ':date: *Call booked:* ' + esc(b.name || b.email) + ' (' + esc(b.email) + ')',
  '*When:* ' + esc(when(b.start)) + ' to ' + esc(hhmm(b.end)) + ' (Manila time)',
  p.dealId ? '*Deal:* ' + esc(p.dealName) + (p.moveToCallBooked ? ' · moved to Call booked' : '') : '_No open TCA deal: logged on the contact_',
];
const buttons = [{ type: 'button', text: { type: 'plain_text', text: 'Open in HubSpot' }, url, action_id: 'open_record' }];
if (b.joinUrl) buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Google Meet link' }, url: b.joinUrl, action_id: 'open_meet' });
return [{ json: {
  channel: p.bucket === 'Hot' ? CHANNEL.HOT : CHANNEL.LEADS,
  text: 'Call booked: ' + esc(b.name || b.email) + ', ' + esc(when(b.start)),
  blocks: [{ type: 'section', text: { type: 'mrkdwn', text: lines.join('\n') } }, { type: 'actions', elements: buttons }],
  unfurl_links: false,
} }];

